const state={token:localStorage.getItem('chatlk_token'),user:JSON.parse(localStorage.getItem('chatlk_user')||'null'),chats:[],contacts:[],active:null,messages:[],socket:null,groupMembers:[],replyTo:null,typingTimer:null,reconnectTimer:null,recording:null,recordingChunks:[],recordingTimer:null,recordingStartedAt:0,call:null,filter:'all',searchQuery:''};
const app=document.querySelector('#app');
const api=async(path,options={})=>{const headers={Authorization:state.token?`Bearer ${state.token}`:'',...(options.headers||{})};if(!(options.body instanceof FormData))headers['Content-Type']='application/json';const response=await fetch(`/api${path}`,{...options,headers});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Request failed');return data};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const displayName=user=>user?.display_name||user?.displayName||user?.username||'User';
function applyTheme(){const saved=localStorage.getItem('chatlk_theme');document.body.classList.toggle('dark-mode',saved==='dark'||(!saved&&window.matchMedia?.('(prefers-color-scheme: dark)').matches));}
function toggleTheme(){const dark=!document.body.classList.contains('dark-mode');localStorage.setItem('chatlk_theme',dark?'dark':'light');applyTheme();}
let deferredInstallPrompt=null;
function isStandalone(){return window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true;}
function showInstallNotice(){if(isStandalone()||document.querySelector('.install-notice'))return;const ios=/iphone|ipad|ipod/i.test(navigator.userAgent);const notice=document.createElement('aside');notice.className='install-notice';notice.innerHTML='<div class="install-copy"><strong>Install ChatLK</strong><span>'+(ios?'Add ChatLK to your Home Screen for a faster app experience.':'Install ChatLK on your phone for quick access and notifications.')+'</span></div><button class="install-now" type="button">Install</button><button class="install-dismiss" type="button" aria-label="Dismiss">×</button>';document.body.append(notice);notice.querySelector('.install-dismiss').onclick=()=>{notice.remove();sessionStorage.setItem('chatlk_install_notice_dismissed','1')};notice.querySelector('.install-now').onclick=async()=>{if(deferredInstallPrompt){deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;notice.remove()}else{notice.querySelector('.install-copy span').textContent=ios?'Tap Share, then Add to Home Screen.':'Use your browser menu and choose Install app or Add to Home screen.';notice.querySelector('.install-now').textContent='Got it'}};}
function setupPWA(){if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;showInstallNotice()});window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;document.querySelector('.install-notice')?.remove()});if(!isStandalone()&&!sessionStorage.getItem('chatlk_install_notice_dismissed'))setTimeout(showInstallNotice,900);}
function auth(){app.innerHTML=`<section class="auth-screen"><div class="auth-glow auth-glow-one"></div><div class="auth-glow auth-glow-two"></div><div class="auth-frame"><div class="auth-story"><div class="eyebrow"><span class="eyebrow-dot"></span>Private by design · Built for Sri Lanka</div><h1>Conversations that feel <em>closer.</em></h1><p>ChatLK brings your people, communities and everyday moments into one calm, beautifully local space.</p><div class="story-points"><span><b>01</b> Sinhala, Tamil & English</span><span><b>02</b> End-to-end ready experience</span><span><b>03</b> Made for mobile, made for you</span></div><div class="story-orbit"><div class="orbit-card orbit-card-main"><span class="orbit-avatar avatar-mint">ස</span><div><strong>සුභ උදෑසනක්</strong><span>Good morning, Nadee</span></div><span class="orbit-check">✓✓</span></div><div class="orbit-card orbit-card-small"><span class="orbit-spark">✦</span><div><strong>12</strong><span>new moments</span></div></div></div></div><div class="auth-panel card"><div class="auth-panel-head"><div class="brand-lockup"><span class="brand-mark">✦</span><span><b>Chat</b>LK</span></div><span class="secure-pill"><span class="secure-dot"></span> Secure</span></div><div class="auth-heading"><span class="auth-kicker">Welcome back</span><h2>Pick up where you left off.</h2><p>Sign in to your private conversations and communities.</p></div><form id="login"><div class="field"><label for="login-identifier">Username or phone</label><div class="input-shell"><span class="input-icon">@</span><input id="login-identifier" name="identifier" autocomplete="username" placeholder="you or +94 77 123 4567" required></div></div><div class="field"><label for="login-password">Password</label><div class="input-shell"><span class="input-icon">⌁</span><input id="login-password" name="password" type="password" autocomplete="current-password" placeholder="Your password" required></div></div><div class="form-row"><label class="check-row"><input type="checkbox"><span>Remember me</span></label><span class="muted-link">Private space</span></div><button class="primary auth-submit" type="submit"><span>Sign in to ChatLK</span><span class="button-arrow">→</span></button></form><div class="auth-divider"><span>New to ChatLK?</span></div><button class="secondary auth-secondary" type="button" id="show-register">Create your account <span>↗</span></button><p class="error" id="error" role="alert"></p><p class="legal-copy">By continuing, you agree to keep ChatLK kind, safe and respectful.</p></div></div></section>`;document.querySelector('#login').onsubmit=login;document.querySelector('#show-register').onclick=register}
function register(){app.innerHTML=`<section class="auth-screen"><div class="auth-glow auth-glow-one"></div><div class="auth-glow auth-glow-two"></div><div class="auth-frame"><div class="auth-story"><div class="eyebrow"><span class="eyebrow-dot"></span>Your next chapter starts here</div><h1>Make room for the people who <em>matter.</em></h1><p>Create a private home for your conversations, memories and everyday check-ins.</p><div class="story-points"><span><b>01</b> One account, every language</span><span><b>02</b> Rich media and voice notes</span><span><b>03</b> Groups that feel personal</span></div><div class="story-orbit"><div class="orbit-card orbit-card-main"><span class="orbit-avatar avatar-lilac">ආ</span><div><strong>Ayubowan, friend</strong><span>Welcome to your new space</span></div><span class="orbit-check">✦</span></div><div class="orbit-card orbit-card-small"><span class="orbit-spark">◌</span><div><strong>∞</strong><span>moments to share</span></div></div></div></div><div class="auth-panel card"><div class="auth-panel-head"><div class="brand-lockup"><span class="brand-mark">✦</span><span><b>Chat</b>LK</span></div><span class="secure-pill"><span class="secure-dot"></span> Your space</span></div><div class="auth-heading"><span class="auth-kicker">Create your account</span><h2>A calmer way to stay close.</h2><p>Join ChatLK and start your private, local-first experience.</p></div><form id="register"><div class="field"><label for="register-username">Username</label><div class="input-shell"><span class="input-icon">@</span><input id="register-username" name="username" pattern="[A-Za-z0-9_]{3,20}" autocomplete="username" placeholder="your_name" required></div></div><div class="form-grid"><div class="field"><label for="register-phone">Phone</label><div class="input-shell"><span class="input-icon">+</span><input id="register-phone" name="phone" inputmode="tel" placeholder="+94 77 123 4567" required></div></div><div class="field"><label for="register-display">Display name</label><div class="input-shell"><span class="input-icon">✦</span><input id="register-display" name="display_name" autocomplete="name" placeholder="How should we call you?" required></div></div></div><div class="field"><label for="register-password">Password</label><div class="input-shell"><span class="input-icon">⌁</span><input id="register-password" name="password" type="password" minlength="8" autocomplete="new-password" placeholder="At least 8 characters" required></div></div><button class="primary auth-submit" type="submit"><span>Create my ChatLK account</span><span class="button-arrow">→</span></button></form><div class="auth-divider"><span>Already have an account?</span></div><button class="secondary auth-secondary" type="button" onclick="location.reload()">Back to sign in <span>↗</span></button><p class="error" id="error" role="alert"></p><p class="legal-copy">We use your phone number to help people find you. It stays protected in your account.</p></div></div></section>`;document.querySelector('#register').onsubmit=async e=>{e.preventDefault();try{const data=await api('/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});saveSession(data);render()}catch(error){document.querySelector('#error').textContent=error.message}}}
async function login(e){e.preventDefault();try{const data=await api('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});saveSession(data);render()}catch(error){document.querySelector('#error').textContent=error.message}}
function saveSession(data){state.token=data.token;state.user=data.user;localStorage.setItem('chatlk_token',state.token);localStorage.setItem('chatlk_user',JSON.stringify(state.user))}
async function render(){if(!state.token)return auth();try{const [chatData,contactData,me]=await Promise.all([api('/chats'),api('/contacts'),api('/users/me')]);state.chats=chatData.chats||[];state.contacts=contactData.contacts||[];state.user=me.user||state.user;localStorage.setItem('chatlk_user',JSON.stringify(state.user))}catch(error){state.token=null;localStorage.removeItem('chatlk_token');return auth()}app.innerHTML=`<div class="shell"><aside class="sidebar"><header class="home-header"><div class="brand-lockup sidebar-brand"><span class="brand-mark">✦</span><span><b>Chat</b>LK</span></div><div class="header-actions"><span class="online-label"><span class="online-dot"></span> Online</span><button class="icon-button" id="camera-btn" aria-label="Camera">▣</button><button class="icon-button" id="menu-btn" aria-label="Toggle theme">◐</button></div></header><div class="workspace-intro"><div><span class="eyebrow-label">YOUR SPACE</span><h1>Good to see you, ${esc(displayName(state.user).split(' ')[0])}.</h1></div><button class="new-chat-button" id="new-chat" aria-label="Start a new chat"><span>＋</span> New chat</button></div><div class="home-tools"><label class="search-wrap"><span aria-hidden="true">⌕</span><input class="search" id="search" placeholder="Search conversations" aria-label="Search chats"><kbd>⌘ K</kbd></label><div class="filter-row" role="tablist" aria-label="Chat filters"><button class="filter-chip active" data-filter="all">All <span class="count-badge"></span></button><button class="filter-chip" data-filter="unread">Unread <span class="count-badge">0</span></button><button class="filter-chip" data-filter="favorites">Favorites</button><button class="filter-chip" data-filter="groups">Groups</button></div></div><div class="quick-row"><button class="quick-item"><span class="quick-icon">▣</span><span><strong>Locked chats</strong><small>Your private corner</small></span><span class="quick-arrow">→</span></button><button class="quick-item"><span class="quick-icon quick-icon-soft">◌</span><span><strong>Archived</strong><small>Quietly out of view</small></span><span class="quick-count">0</span></button></div><div class="list-heading"><span>RECENT CONVERSATIONS</span><span class="list-line"></span></div><div id="chat-list"></div><div class="sidebar-actions"><button class="account-card" id="profile-btn"><span class="avatar profile-mini-avatar">${esc(displayName(state.user)[0])}</span><span class="account-copy"><strong>${esc(displayName(state.user))}</strong><span>@${esc(state.user.username || 'chatlk-user')}</span></span><span class="account-arrow">↗</span></button><div class="utility-actions"><button class="outline-btn" id="contacts-btn">Contacts</button><button class="outline-btn" id="group-btn">＋ Group</button><button class="outline-btn" id="settings-btn">⚙ Settings</button></div><button class="link logout-link" id="logout"><span>↗</span> Log out</button></div><nav class="bottom-nav" aria-label="Main navigation"><button class="nav-item active"><span>▤</span><b>Chats</b></button><button class="nav-item" id="updates-btn"><span>◉</span><b>Updates</b></button><button class="nav-item"><span>♧</span><b>Circles</b></button><button class="nav-item"><span>⌕</span><b>Calls</b></button></nav><button class="fab" id="fab-new" aria-label="New chat">＋</button></aside><section class="main"><header class="topbar chat-topbar"><button class="mobile-back" id="mobile-back" aria-label="Back to chats">‹</button><div class="avatar-wrap"><div class="avatar chat-avatar">${esc(displayName(state.user)[0])}</div><span class="presence-dot online" id="topbar-presence-dot" title="Online"></span></div><div class="topbar-copy"><span class="chat-overline">CURRENT CONVERSATION</span><strong id="chat-title">Select a conversation</strong><div id="presence">Ready when you are</div></div><div class="chat-actions"><button type="button" id="chat-settings-btn" aria-label="Chat settings">⚙</button><button type="button" id="video-call-btn" aria-label="Video call">▣</button><button type="button" id="voice-call-btn" aria-label="Voice call">☎</button><button type="button" aria-label="More options">⋮</button></div></header><div class="messages" id="messages"><div class="empty chat-welcome"><div class="welcome-mark">✦</div><span class="eyebrow-label">YOUR PRIVATE SPACE</span><h2>Make a little room for connection.</h2><p>Pick a conversation from the left, or start something new. Your messages, your pace.</p><div class="welcome-hints"><span>⌘ Search chats</span><span>↗ Share a moment</span><span>◌ Stay connected</span></div></div></div><div id="reply-preview" class="reply-preview hidden"></div><form class="composer whatsapp-composer" id="composer"><button type="button" class="composer-icon" id="emoji-btn" aria-label="Add emoji">☺</button><input name="text" placeholder="Write something kind…" autocomplete="off" aria-label="Message"><button type="button" class="composer-icon" id="attach-btn" aria-label="Attach file">⊕</button><input type="file" id="media-input" class="hidden" accept="image/jpeg,image/png,image/webp,image/gif,application/pdf"><button type="button" class="composer-icon" id="camera-chat-btn" aria-label="Camera">▣</button><button type="button" class="mic-send" id="voice-btn" aria-label="Record voice note">●</button></form><div id="call-overlay" class="call-overlay hidden"><video id="remote-video" class="remote-video" autoplay playsinline></video><video id="local-video" class="local-video" autoplay muted playsinline></video><div class="call-status" id="call-status">Calling…</div><div class="call-controls"><button type="button" id="mute-call" aria-label="Mute microphone">🎙</button><button type="button" id="share-screen" aria-label="Share screen">▣</button><button type="button" id="end-call" class="end-call" aria-label="End call">☎</button></div></div></section></div>`;document.querySelector('#logout').onclick=logout;document.querySelector('#menu-btn').onclick=toggleTheme;document.querySelector('#menu-btn').title='Toggle light / dark mode';document.querySelector('#updates-btn').onclick=showStatuses;document.querySelector('#profile-btn').onclick=showProfile;document.querySelector('#settings-btn').onclick=()=>showChatSettingsModal(null);document.querySelector('#chat-settings-btn').onclick=()=>showChatSettingsModal(state.active);document.querySelector('#new-chat').onclick=showNewChat;document.querySelector('#fab-new').onclick=showNewChat;document.querySelector('#contacts-btn').onclick=showContacts;document.querySelector('#group-btn').onclick=showGroup;document.querySelector('#mobile-back').onclick=()=>document.querySelector('.shell').classList.remove('chat-open');document.querySelector('.chat-avatar').onclick=showChatInfo;document.querySelector('#chat-title').onclick=showChatInfo;document.querySelector('#video-call-btn').onclick=()=>startCall('video');document.querySelector('#voice-call-btn').onclick=()=>startCall('audio');setupCallUi();document.querySelector('#composer').onsubmit=send;document.querySelector('#composer input').oninput=handleTyping;document.querySelector('#emoji-btn').onclick=()=>{const input=document.querySelector('#composer input');input.value+='🙂';input.focus()};document.querySelector('#attach-btn').onclick=()=>document.querySelector('#media-input').click();document.querySelector('#media-input').onchange=e=>{if(e.target.files[0])uploadMedia(e.target.files[0]);e.target.value=''};document.querySelector('#camera-chat-btn').onclick=()=>document.querySelector('#presence').textContent='Camera is coming soon';document.querySelector('#voice-btn').onclick=toggleVoiceRecording;document.querySelector('#search').oninput=e=>{state.searchQuery=e.target.value.trim().toLowerCase();drawChats()};document.querySelectorAll('.filter-chip[data-filter]').forEach(button=>button.onclick=()=>{state.filter=button.dataset.filter;document.querySelectorAll('.filter-chip').forEach(item=>item.classList.toggle('active',item===button));drawChats()});drawChats()}
function logout(){state.socket?.close();state.token=null;state.user=null;localStorage.removeItem('chatlk_token');localStorage.removeItem('chatlk_user');auth()}
function drawChats(){const list=document.querySelector('#chat-list');if(!list)return;const chats=state.chats.filter(chat=>{const name=(chat.name||'Direct chat').toLowerCase();const matches=!state.searchQuery||name.includes(state.searchQuery)||(chat.last_message||'').toLowerCase().includes(state.searchQuery);const filterMatch=state.filter==='all'||(state.filter==='groups'&&chat.type==='group')||(state.filter==='unread'&&Number(chat.unread_count)>0);return matches&&filterMatch});const unreadTotal=state.chats.reduce((sum,chat)=>sum+Number(chat.unread_count||0),0);const badge=document.querySelector('.count-badge');if(badge)badge.textContent=unreadTotal||'';if(!chats.length){list.innerHTML='<p class="empty chat-empty">No conversations yet.<br>Tap <b>＋</b> to begin.</p>';return}list.replaceChildren();for(const chat of chats){const item=document.createElement('button');item.className='chat-item '+(Number(chat.unread_count)>0?'has-unread':'');const name=chat.name||'Direct chat';const time=chat.last_message_at?new Date(chat.last_message_at).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}):'';const mine=chat.last_message_sender_id===state.user?.id;const preview=chat.last_message?(mine?'You: ':'')+(chat.last_message):'No messages yet';const isOnline=Boolean(chat.peer_is_online);item.innerHTML='<span class="avatar-wrap"><span class="avatar">'+esc(name[0])+'</span>'+(chat.type!=='group'?'<span class="presence-dot '+(isOnline?'online':'offline')+'" title="'+(isOnline?'Online':'Offline')+'"></span>':'')+'</span><span class="chat-meta"><strong>'+esc(name)+'</strong><span>'+esc(preview)+'</span></span><span class="chat-side"><span class="chat-time">'+esc(time)+'</span>'+(Number(chat.unread_count)>0?'<span class="unread-badge">'+chat.unread_count+'</span>':'')+'</span>';item.onclick=()=>openChat(chat);list.append(item)}}
function modal(title,body){const node=document.createElement('div');node.className='modal-backdrop';node.innerHTML=`<section class="modal card" role="dialog" aria-modal="true"><h2>${title}</h2>${body}<button class="link" id="close-modal">Cancel</button></section>`;document.body.append(node);node.querySelector('#close-modal').onclick=()=>node.remove();return node}
function renderStatusMedia(status,box){if(!status.media_url)return;loadMedia(status.media_url).then(url=>{if(status.media_type&&status.media_type.startsWith('video/')){const video=document.createElement('video');video.src=url;video.controls=true;video.playsInline=true;video.className='status-media';box.prepend(video)}else{const image=document.createElement('img');image.src=url;image.alt='Status media';image.className='status-media';box.prepend(image)}}).catch(()=>{})}
async function createStatus(event,modalNode){event.preventDefault();const form=event.target;const text=form.elements.text.value.trim();const file=form.elements.file.files[0];const error=modalNode.querySelector('#status-error');try{let mediaUrl=null,mediaType=null;if(file){const upload=new FormData();upload.append('file',file);const result=await api('/media/upload',{method:'POST',body:upload});mediaUrl=result.url;mediaType=file.type}await api('/statuses',{method:'POST',body:JSON.stringify({text,mediaUrl,mediaType})});modalNode.remove();showStatuses()}catch(err){error.textContent=err.message}}
async function showStatuses(){try{const data=await api('/statuses');const statuses=data.statuses||[];const cards=statuses.map(status=>{const own=status.user_id===state.user?.id;const time=new Date(status.created_at).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'});return `<article class="status-card ${status.viewed?'viewed':''}" data-status-id="${status.id}"><div class="status-head"><div class="avatar status-avatar">${esc((status.display_name||status.username||'U')[0])}</div><div><strong>${esc(own?'My status':status.display_name||status.username)}</strong><span>${esc(time)} · ${Math.max(0,Math.round((status.expires_at-Date.now())/3600000))}h left</span></div>${own?'<button type="button" class="danger-btn status-delete">Delete</button>':''}</div><div class="status-content">${status.text?`<p>${esc(status.text)}</p>`:''}</div>${own?`<small class="status-viewers">${status.viewer_count||0} views</small>`:''}</article>`}).join('');const m=modal('Updates / Status',`<form id="status-form" class="inline-form"><textarea name="text" maxlength="700" rows="2" placeholder="Type a status…"></textarea><input type="file" name="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4"><button class="primary">Post status</button><p class="error" id="status-error"></p></form><div class="status-list">${cards||'<p class="empty">No active statuses yet.</p>'}</div>`);m.querySelector('#status-form').onsubmit=e=>createStatus(e,m);for(const status of statuses){const card=m.querySelector(`[data-status-id="${status.id}"]`);if(status.media_url)renderStatusMedia(status,card.querySelector('.status-content'));card.onclick=async e=>{if(e.target.closest('.status-delete'))return;await api(`/statuses/${status.id}/view`,{method:'POST'}).catch(()=>{});card.classList.add('viewed')};card.querySelector('.status-delete')?.addEventListener('click',async()=>{await api(`/statuses/${status.id}`,{method:'DELETE'});m.remove();showStatuses()})}}catch(error){alert(error.message)}}
function showProfile(){const u=state.user||{};const m=modal('Your profile',`<div class="profile-hero"><div class="profile-avatar-wrap"><div class="avatar profile-avatar" id="profile-avatar">${esc(displayName(u)[0])}</div><label class="avatar-upload" aria-label="Change profile photo">＋<input type="file" id="avatar-input" accept="image/jpeg,image/png,image/webp,image/gif"></label></div><div><h3>${esc(displayName(u))}</h3><p>@${esc(u.username)}${(u.is_verified||u.isVerified)?' · ✓ Verified':''}</p></div></div><form id="profile-form" class="inline-form"><div class="field"><label>Display name</label><input name="display_name" maxlength="80" value="${esc((u.display_name||u.displayName))}" required></div><div class="field"><label>About / bio</label><textarea name="bio" maxlength="500" rows="3">${esc(u.bio)}</textarea></div><div class="field"><label>Language</label><select name="language"><option value="si" ${u.language==='si'?'selected':''}>සිංහල</option><option value="ta" ${u.language==='ta'?'selected':''}>தமிழ்</option><option value="en" ${u.language==='en'?'selected':''}>English</option></select></div><button class="primary">Save profile</button><p class="error" id="profile-error"></p></form><div class="profile-details"><span>Phone</span><b>${esc(u.phone||'Not available')}</b><span>Last seen</span><b>${(u.last_seen||u.lastSeen)?new Date((u.last_seen||u.lastSeen)).toLocaleString():'Recently active'}</b></div>`);if((u.avatar_url||u.avatarUrl))loadMedia((u.avatar_url||u.avatarUrl)).then(url=>{m.querySelector('#profile-avatar').innerHTML=`<img src="${url}" alt="Profile photo">`}).catch(()=>{});m.querySelector('#avatar-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const form=new FormData();form.append('file',file);const data=await api('/users/me/avatar',{method:'POST',body:form});state.user.avatar_url=data.url;const url=await loadMedia(data.url);m.querySelector('#profile-avatar').innerHTML=`<img src="${url}" alt="Profile photo">`}catch(error){m.querySelector('#profile-error').textContent=error.message}};m.querySelector('#profile-form').onsubmit=async e=>{e.preventDefault();try{const data=await api('/users/me',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.user=data.user;localStorage.setItem('chatlk_user',JSON.stringify(state.user));m.remove();render()}catch(error){m.querySelector('#profile-error').textContent=error.message}}}
function showNewChat(){const m=modal('Start a new chat',`<p>Search by username, phone, or display name.</p><input class="search" id="user-query" placeholder="e.g. user_name or +9477..." autofocus><div id="user-results"><p class="empty">Type at least 2 characters.</p></div>`);m.querySelector('#user-query').oninput=searchUsers}
let searchTimer;function searchUsers(e){clearTimeout(searchTimer);const value=e.target.value.trim(),results=e.target.closest('.modal').querySelector('#user-results');if(value.length<2){results.innerHTML='<p class="empty">Type at least 2 characters.</p>';return}searchTimer=setTimeout(async()=>{try{const data=await api(`/users/search?q=${encodeURIComponent(value)}`);results.replaceChildren();if(!data.users?.length){results.innerHTML='<p class="empty">No users found.</p>';return}for(const user of data.users){const button=document.createElement('button');button.className='chat-item';button.innerHTML=`<span class="avatar">${esc(displayName(user)[0])}</span><span class="chat-meta"><strong>${esc(displayName(user))}</strong><span>@${esc(user.username)}</span></span>`;button.onclick=()=>createDirectChat(user);results.append(button)}}catch(error){results.innerHTML=`<p class="error">${esc(error.message)}</p>`}},250)}
async function createDirectChat(user){try{const data=await api('/chats',{method:'POST',body:JSON.stringify({type:'direct',participantIds:[user.id]})});document.querySelector('.modal-backdrop')?.remove();await refreshChats();const chat=state.chats.find(item=>item.id===data.id);if(chat)openChat(chat)}catch(error){const results=document.querySelector('.modal-backdrop #user-results');if(results)results.innerHTML=`<p class="error">${esc(error.message)}</p>`}}
async function refreshChats(){const data=await api('/chats');state.chats=data.chats||[];drawChats()}
async function refreshContacts(){const data=await api('/contacts');state.contacts=data.contacts||[]}
function showContacts(){const m=modal('Contacts',`<p>Add people by username or phone. You can block or remove saved contacts.</p><form id="add-contact" class="inline-form"><input name="identifier" placeholder="username or +9477..." required><input name="nickname" placeholder="Nickname (optional)"><button class="primary">Add contact</button></form><p class="error" id="contact-error"></p><div id="invite-area" class="invite-area hidden"></div><div id="contact-list"></div>`);m.querySelector('#add-contact').onsubmit=addContact;drawContacts(m)}
function drawContacts(m){const list=m.querySelector('#contact-list');if(!state.contacts.length){list.innerHTML='<p class="empty">No contacts saved yet.</p>';return}list.replaceChildren();for(const contact of state.contacts){const item=document.createElement('div');item.className='contact-row';item.innerHTML=`<span class="avatar-wrap"><span class="avatar">${esc(displayName(contact)[0])}</span><span class="presence-dot ${contact.is_online?'online':'offline'}" title="${contact.is_online?'Online':'Offline'}"></span></span><span class="chat-meta"><strong>${esc(contact.nickname||displayName(contact))}</strong><span>@${esc(contact.username)} · ${contact.is_blocked?'Blocked':(contact.is_online?'Online':'Offline')}</span></span><button class="outline-btn contact-chat">Chat</button><button class="danger-btn contact-block">${contact.is_blocked?'Unblock':'Block'}</button><button class="danger-btn contact-remove">Remove</button>`;item.querySelector('.contact-chat').onclick=()=>createDirectChat(contact);item.querySelector('.contact-block').onclick=()=>updateContact(contact.id,!contact.is_blocked,m);item.querySelector('.contact-remove').onclick=()=>removeContact(contact.id,m);list.append(item)}}
async function addContact(e){e.preventDefault();const m=e.target.closest('.modal');try{await api('/contacts',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await refreshContacts();e.target.reset();drawContacts(m)}catch(error){const value=e.target.elements.identifier.value.trim();m.querySelector('#contact-error').textContent=error.message;const area=m.querySelector('#invite-area');area.className='invite-area';area.innerHTML=`<span>${esc(value)} is not registered on ChatLK.</span><button type="button" class="primary invite-button">Invite</button>`;area.querySelector('.invite-button').onclick=()=>inviteContact(value)}}
async function updateContact(id,isBlocked,m){try{await api(`/contacts/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({is_blocked:isBlocked})});await refreshContacts();drawContacts(m)}catch(error){m.querySelector('#contact-error').textContent=error.message}}
async function removeContact(id,m){try{await api(`/contacts/${encodeURIComponent(id)}`,{method:'DELETE'});await refreshContacts();drawContacts(m)}catch(error){m.querySelector('#contact-error').textContent=error.message}}
function showGroup(){state.groupMembers=[];const m=modal('Create a group',`<p>Select contacts or search users to add members.</p><div class="field"><label>Group name</label><input id="group-name" maxlength="120" placeholder="e.g. Family"></div><input class="search" id="group-query" placeholder="Search users"><div id="group-selected" class="selected-users"></div><div id="group-results"><p class="empty">Select at least one other user.</p></div><p class="error" id="group-error"></p><button class="primary" id="create-group">Create group</button>`);m.querySelector('#group-query').oninput=e=>searchGroupUsers(e,m);m.querySelector('#create-group').onclick=()=>createGroup(m)}
function drawSelected(m){const box=m.querySelector('#group-selected');box.replaceChildren();for(const user of state.groupMembers){const chip=document.createElement('span');chip.className='user-chip';chip.textContent=displayName(user);const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label',`Remove ${displayName(user)}`);remove.onclick=()=>{state.groupMembers=state.groupMembers.filter(item=>item.id!==user.id);drawSelected(m)};chip.append(remove);box.append(chip)}}
let groupTimer;function searchGroupUsers(e,m){clearTimeout(groupTimer);const value=e.target.value.trim(),results=m.querySelector('#group-results');if(value.length<2){results.innerHTML='<p class="empty">Type at least 2 characters.</p>';return}groupTimer=setTimeout(async()=>{try{const data=await api(`/users/search?q=${encodeURIComponent(value)}`);results.replaceChildren();for(const user of data.users||[]){if(state.groupMembers.some(item=>item.id===user.id))continue;const button=document.createElement('button');button.className='chat-item';button.innerHTML=`<span class="avatar">${esc(displayName(user)[0])}</span><span class="chat-meta"><strong>${esc(displayName(user))}</strong><span>@${esc(user.username)}</span></span>`;button.onclick=()=>{state.groupMembers.push(user);drawSelected(m);button.remove()};results.append(button)}if(!results.children.length)results.innerHTML='<p class="empty">No users found.</p>'}catch(error){results.innerHTML=`<p class="error">${esc(error.message)}</p>`}},250)}
async function createGroup(m){const name=m.querySelector('#group-name').value.trim();if(!name||!state.groupMembers.length){m.querySelector('#group-error').textContent='Enter a group name and select at least one member.';return}try{const data=await api('/chats',{method:'POST',body:JSON.stringify({type:'group',name,participantIds:state.groupMembers.map(user=>user.id)})});m.remove();await refreshChats();const chat=state.chats.find(item=>item.id===data.id);if(chat)openChat(chat)}catch(error){m.querySelector('#group-error').textContent=error.message}}
async function openChat(chat){state.active=chat;state.replyTo=null;document.querySelector('.shell').classList.add('chat-open');document.querySelector('#chat-title').textContent=chat.name||'Direct chat';document.querySelector('#presence').textContent='Connecting…';try{const data=await api(`/chats/${chat.id}/messages`);state.messages=(data.messages||[]).reverse();drawMessages();const unread=state.messages.filter(message=>{const sender=message.sender_id||message.senderId;return sender!==state.user?.id&&message.status!=='read'});if(unread.length)await Promise.all(unread.map(markRead));await refreshChats();connectSocket(chat);if(chat.type!=='group'){api(`/chats/${chat.id}`).then(chatInfo=>{const peer=chatInfo.participants?.find(p=>p.id!==state.user?.id);if(peer){api(`/users/${peer.id}/presence`).then(p=>{const dot=document.querySelector('#topbar-presence-dot');if(dot){dot.className='presence-dot '+(p.isOnline?'online':'offline');dot.title=p.isOnline?'Online':'Offline';}if(!state.socket||state.socket.readyState!==WebSocket.OPEN){document.querySelector('#presence').textContent=p.isOnline?'Online':'last seen recently';}}).catch(()=>{});}}).catch(()=>{});}}catch(error){document.querySelector('#presence').textContent=error.message}}
function connectSocket(chat){state.socket?.close();const protocol=location.protocol==='https:'?'wss:':'ws:';state.socket=new WebSocket(`${protocol}//${location.host}/ws?userId=${encodeURIComponent(state.user.id)}&chatId=${encodeURIComponent(chat.id)}&token=${encodeURIComponent(state.token)}`);state.socket.onopen=()=>document.querySelector('#presence').textContent='Online';state.socket.onclose=()=>{if(state.active?.id===chat.id){document.querySelector('#presence').textContent='Reconnecting…';clearTimeout(state.reconnectTimer);state.reconnectTimer=setTimeout(()=>connectSocket(chat),1500)}};state.socket.onerror=()=>document.querySelector('#presence').textContent='Connection error';state.socket.onmessage=event=>{const data=JSON.parse(event.data);if(data.type==='message'){state.messages.push(data.message);drawMessages();markRead(data.message)}if(data.type==='presence'&&data.userId!==state.user.id){const isOnline=data.status==='online';document.querySelector('#presence').textContent=isOnline?'Online':'Offline';const dot=document.querySelector('#topbar-presence-dot');if(dot){dot.className='presence-dot '+(isOnline?'online':'offline');dot.title=isOnline?'Online':'Offline';}}if(data.type==='typing'&&data.userId!==state.user.id)document.querySelector('#presence').textContent=data.isTyping?'Typing…':'Online';if(data.type==='read'){const message=state.messages.find(item=>item.id===data.messageId);if(message)message.status='read';drawMessages()}if(data.type==='call-offer'&&data.userId!==state.user.id)receiveCall(data.payload,data.userId);if(data.type==='call-answer'&&state.call?.pc)data.payload&&state.call.pc.setRemoteDescription(data.payload).catch(()=>{});if(data.type==='ice-candidate'&&state.call?.pc&&data.payload)state.call.pc.addIceCandidate(data.payload).catch(()=>{});if(data.type==='call-end')endCall(false)}}
function drawMessages(){const container=document.querySelector('#messages');if(!container)return;container.replaceChildren();if(!state.messages.length){container.innerHTML='<div class="empty">No messages yet. Say hello.</div>';return}let lastDay='';for(const message of state.messages){const date=new Date(message.created_at||message.createdAt);const day=date.toLocaleDateString();if(day!==lastDay){const divider=document.createElement('div');divider.className='date-divider';divider.textContent=day;container.append(divider);lastDay=day}const mine=message.sender_id===state.user?.id||message.senderId===state.user?.id;const bubble=document.createElement('article');bubble.className=`bubble whatsapp-bubble ${mine?'sent':''}`;bubble.dataset.id=message.id;if(!mine&&state.active?.type==='group'){const sender=document.createElement('strong');sender.className='sender-name';sender.textContent=message.sender_name||message.senderName||'Member';bubble.append(sender)}const text=document.createElement('p');text.textContent=message.text||'[media]';if(message.media_url||message.mediaUrl){const mediaUrl=message.media_url||message.mediaUrl;if(message.message_type==='image'||message.messageType==='image'){text.textContent='Loading image…';loadMedia(mediaUrl).then(url=>{const image=document.createElement('img');image.className='message-image';image.src=url;image.alt=message.text||'Shared image';text.replaceWith(image)}).catch(()=>text.textContent='Image unavailable')}else if(message.message_type==='audio'||message.messageType==='audio'){text.textContent='Loading voice note…';loadMedia(mediaUrl).then(url=>{const audio=document.createElement('audio');audio.className='voice-player';audio.controls=true;audio.preload='metadata';audio.src=url;text.replaceWith(audio)}).catch(()=>text.textContent='Voice note unavailable')}else{const link=document.createElement('button');link.type='button';link.className='document-link';link.textContent=`▧ ${message.text||'Download document'}`;link.onclick=async()=>{try{const url=await loadMedia(mediaUrl);const anchor=document.createElement('a');anchor.href=url;anchor.download=message.text||'download';anchor.click()}catch(error){document.querySelector('#presence').textContent=error.message}};text.replaceWith(link)}}const meta=document.createElement('small');const ticks=message.status==='read'?'✓✓':message.status==='delivered'?'✓✓':'✓';meta.innerHTML=`${date.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}${message.is_edited?' · edited':''}${mine?` <span class="message-ticks ${message.status==='read'?'read':''}" aria-label="${message.status||'sent'}">${ticks}</span>`:''}`;bubble.append(text,meta);bubble.onclick=()=>showMessageActions(message,bubble);container.append(bubble)}container.scrollTop=container.scrollHeight}
function showMessageActions(message,bubble){document.querySelector('.message-actions')?.remove();const mine=message.sender_id===state.user?.id||message.senderId===state.user?.id;const menu=document.createElement('div');menu.className='message-actions';menu.innerHTML=`<button data-action="reply">Reply</button>${mine?'<button data-action="edit">Edit</button><button data-action="delete">Delete</button>':''}<button data-action="copy">Copy</button>`;bubble.append(menu);menu.onclick=async e=>{const action=e.target.dataset.action;if(action==='reply'){state.replyTo=message;drawReplyPreview()}if(action==='copy')await navigator.clipboard?.writeText(message.text||'');if(action==='edit')editMessage(message);if(action==='delete')deleteMessage(message);menu.remove()};setTimeout(()=>menu.remove(),4000)}
function drawReplyPreview(){const box=document.querySelector('#reply-preview');if(!state.replyTo){box.className='reply-preview hidden';return}box.className='reply-preview';box.innerHTML=`Replying to: <b>${esc((state.replyTo.text||'[media]').slice(0,100))}</b><button type="button" id="cancel-reply">×</button>`;box.querySelector('#cancel-reply').onclick=()=>{state.replyTo=null;drawReplyPreview()}}
async function editMessage(message){const text=prompt('Edit message',message.text||'');if(text===null||!text.trim())return;try{await api(`/messages/${message.id}`,{method:'PUT',body:JSON.stringify({text})});message.text=text.trim();message.is_edited=1;drawMessages()}catch(error){alert(error.message)}}
async function deleteMessage(message){if(!confirm('Delete this message?'))return;try{await api(`/messages/${message.id}`,{method:'DELETE'});state.messages=state.messages.filter(item=>item.id!==message.id);drawMessages()}catch(error){alert(error.message)}}
function handleTyping(e){if(!state.socket||state.socket.readyState!==WebSocket.OPEN)return;state.socket.send(JSON.stringify({type:'typing',isTyping:Boolean(e.target.value.trim())}));clearTimeout(state.typingTimer);state.typingTimer=setTimeout(()=>state.socket?.send(JSON.stringify({type:'typing',isTyping:false})),900)}
function inviteContact(phone){const text=`Join me on ChatLK: ${location.origin}`;const link=`https://wa.me/${phone.replace(/[^0-9]/g,'')}?text=${encodeURIComponent(text)}`;if(navigator.share)navigator.share({title:'Join ChatLK',text,url:link}).catch(()=>{});else{navigator.clipboard?.writeText(link);alert('Invite link copied to clipboard.')}}
function showChatInfo(){if(!state.active)return;api(`/chats/${state.active.id}`).then(data=>{const people=data.participants||[];const peopleHtml=people.map(user=>{const seen=user.last_seen?new Date(user.last_seen).toLocaleString():'Recently active';return `<div class="detail-person"><div class="avatar detail-avatar">${esc(displayName(user)[0])}</div><div><b>${esc(displayName(user))}</b><span>@${esc(user.username)} · ${esc(user.role)}</span><span>${esc(user.phone||'Phone unavailable')}</span><span>${esc(user.bio||'No bio added')}</span><span>${esc(user.language==='si'?'සිංහල':user.language==='ta'?'தமிழ்':'English')} · ${esc(seen)}</span></div></div>`}).join('');const heroName=state.active.name||'Direct chat';const modalNode=modal(state.active.type==='group'?'Group details':'User details',`<div class="chat-detail-hero"><div class="avatar large-avatar" id="chat-detail-avatar">${esc(heroName[0])}</div><h3>${esc(heroName)}</h3><p>${state.active.type==='group'?'Group conversation':'Profile and contact details'}</p></div><div class="detail-list">${peopleHtml}</div>`);const first=people.find(user=>user.id!==state.user?.id);if(first?.avatar_url)loadMedia(first.avatar_url).then(url=>{const image=document.createElement('img');image.src=url;image.alt=displayName(first);modalNode.querySelector('#chat-detail-avatar').replaceChildren(image)}).catch(()=>{})}).catch(error=>alert(error.message))}
async function showChatSettingsModal(chat){try{const[settingsData,chatDetail]=await Promise.all([api('/users/me/settings').catch(()=>({autoTranslate:Boolean(state.user?.auto_translate||state.user?.autoTranslate),muteNotifications:Boolean(state.user?.mute_notifications||state.user?.muteNotifications),language:state.user?.language||'si'})),chat?api(`/chats/${chat.id}`).catch(()=>({isMuted:false})):Promise.resolve({isMuted:false})]);let autoTranslate=Boolean(settingsData.autoTranslate);let isMuted=chat?Boolean(chatDetail.isMuted):Boolean(settingsData.muteNotifications);let lang=settingsData.language||state.user?.language||'si';const title=chat?`${esc(chat.name||'Chat')} Settings`:'Chat Preferences';const m=modal(title,`<div class="chat-settings-wrap" style="display:flex;flex-direction:column;gap:16px;"><p style="margin:0;font-size:14px;color:var(--text-muted,#64748b);">Configure real-time translation and mute preferences. Changes are automatically saved to Cloudflare D1.</p><div style="background:var(--bg-card,#f8fafc);border:1px solid var(--border-color,#e2e8f0);border-radius:12px;padding:16px;display:flex;flex-direction:column;gap:14px;"><div style="display:flex;align-items:center;justify-content:space-between;gap:12px;"><div><strong style="display:block;font-size:15px;color:var(--text-main,#0f172a);">Auto-Translate Messages</strong><small style="color:var(--text-muted,#64748b);">Automatically translate incoming foreign language messages into your language</small></div><button type="button" id="toggle-at-btn" class="outline-btn" style="min-width:90px;font-weight:600;padding:6px 12px;border-radius:20px;cursor:pointer;background:${autoTranslate?'#0284c7':'transparent'};color:${autoTranslate?'#fff':'inherit'};border-color:${autoTranslate?'#0284c7':'#cbd5e1'};">${autoTranslate?'Enabled':'Disabled'}</button></div><div id="target-lang-row" style="display:${autoTranslate?'flex':'none'};align-items:center;justify-content:space-between;border-top:1px dashed var(--border-color,#e2e8f0);padding-top:10px;"><span style="font-size:13px;color:var(--text-muted,#64748b);">Target language:</span><select id="target-lang-select" style="padding:4px 8px;border-radius:8px;border:1px solid #cbd5e1;background:#fff;"><option value="si" ${lang==='si'?'selected':''}>සිංහල (Sinhala)</option><option value="ta" ${lang==='ta'?'selected':''}>தமிழ் (Tamil)</option><option value="en" ${lang==='en'?'selected':''}>English</option></select></div></div><div style="background:var(--bg-card,#f8fafc);border:1px solid var(--border-color,#e2e8f0);border-radius:12px;padding:16px;display:flex;align-items:center;justify-content:space-between;gap:12px;"><div><strong style="display:block;font-size:15px;color:var(--text-main,#0f172a);">Mute Notifications</strong><small style="color:var(--text-muted,#64748b);">${chat?'Silence alerts and push notifications for this conversation':'Silence all push and sound notifications'}</small></div><button type="button" id="toggle-mute-btn" class="outline-btn" style="min-width:90px;font-weight:600;padding:6px 12px;border-radius:20px;cursor:pointer;background:${isMuted?'#ef4444':'transparent'};color:${isMuted?'#fff':'inherit'};border-color:${isMuted?'#ef4444':'#cbd5e1'};">${isMuted?'Muted':'Active'}</button></div><div id="settings-status-msg" style="font-size:12px;color:#10b981;min-height:18px;text-align:right;"></div></div>`);const statusMsg=m.querySelector('#settings-status-msg');const atBtn=m.querySelector('#toggle-at-btn');const langRow=m.querySelector('#target-lang-row');const muteBtn=m.querySelector('#toggle-mute-btn');const langSelect=m.querySelector('#target-lang-select');atBtn.onclick=async()=>{autoTranslate=!autoTranslate;atBtn.disabled=true;try{await api('/users/me/settings',{method:'PATCH',body:JSON.stringify({autoTranslate})});if(state.user){state.user.auto_translate=autoTranslate?1:0;state.user.autoTranslate=autoTranslate;localStorage.setItem('chatlk_user',JSON.stringify(state.user))}atBtn.textContent=autoTranslate?'Enabled':'Disabled';atBtn.style.background=autoTranslate?'#0284c7':'transparent';atBtn.style.color=autoTranslate?'#fff':'inherit';atBtn.style.borderColor=autoTranslate?'#0284c7':'#cbd5e1';langRow.style.display=autoTranslate?'flex':'none';statusMsg.textContent='Auto-translate preference saved to D1';setTimeout(()=>{if(statusMsg)statusMsg.textContent=''},2500)}catch(err){statusMsg.style.color='#ef4444';statusMsg.textContent=err.message}finally{atBtn.disabled=false}};if(langSelect){langSelect.onchange=async()=>{const selected=langSelect.value;try{await api('/users/me',{method:'PUT',body:JSON.stringify({language:selected})});if(state.user){state.user.language=selected;localStorage.setItem('chatlk_user',JSON.stringify(state.user))}statusMsg.textContent='Language saved to D1';setTimeout(()=>{if(statusMsg)statusMsg.textContent=''},2500)}catch(err){statusMsg.style.color='#ef4444';statusMsg.textContent=err.message}}};muteBtn.onclick=async()=>{isMuted=!isMuted;muteBtn.disabled=true;try{if(chat){if(isMuted){await api(`/chats/${chat.id}/mute`,{method:'POST'})}else{await api(`/chats/${chat.id}/mute`,{method:'DELETE'})}}else{await api('/users/me/settings',{method:'PATCH',body:JSON.stringify({muteNotifications:isMuted})});if(state.user){state.user.mute_notifications=isMuted?1:0;state.user.muteNotifications=isMuted;localStorage.setItem('chatlk_user',JSON.stringify(state.user))}}muteBtn.textContent=isMuted?'Muted':'Active';muteBtn.style.background=isMuted?'#ef4444':'transparent';muteBtn.style.color=isMuted?'#fff':'inherit';muteBtn.style.borderColor=isMuted?'#ef4444':'#cbd5e1';statusMsg.textContent='Mute preference saved to D1';setTimeout(()=>{if(statusMsg)statusMsg.textContent=''},2500)}catch(err){statusMsg.style.color='#ef4444';statusMsg.textContent=err.message}finally{muteBtn.disabled=false}}}catch(err){alert('Unable to load settings: '+err.message)}}
function updateRecordingUI(){const button=document.querySelector('#voice-btn');if(!button)return;if(state.recording){button.classList.add('recording');button.textContent='■';button.setAttribute('aria-label','Stop recording');const seconds=Math.floor((Date.now()-state.recordingStartedAt)/1000);document.querySelector('#presence').textContent=`Recording audio… 0:${String(seconds).padStart(2,'0')}`;}}
async function toggleVoiceRecording(){if(state.recording){state.recording.stop();return}if(!state.active){document.querySelector('#presence').textContent='Open a chat to record a voice note';return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){document.querySelector('#presence').textContent='Voice recording is not supported in this browser';return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm;codecs=opus','audio/webm','audio/mp4','audio/ogg'].find(type=>MediaRecorder.isTypeSupported(type))||'';const recorder=mime?new MediaRecorder(stream,{mimeType:mime}):new MediaRecorder(stream);state.recording=recorder;state.recordingChunks=[];state.recordingStartedAt=Date.now();recorder.ondataavailable=e=>{if(e.data.size)state.recordingChunks.push(e.data)};recorder.onstop=async()=>{clearInterval(state.recordingTimer);stream.getTracks().forEach(track=>track.stop());const blob=new Blob(state.recordingChunks,{type:recorder.mimeType||'audio/webm'});state.recording=null;state.recordingChunks=[];const button=document.querySelector('#voice-btn');if(button){button.classList.remove('recording');button.textContent='●';button.setAttribute('aria-label','Record voice note')}if(blob.size>0)await uploadVoice(blob);else document.querySelector('#presence').textContent='Online'};recorder.start();state.recordingTimer=setInterval(updateRecordingUI,250);updateRecordingUI()}catch(error){document.querySelector('#presence').textContent=error.name==='NotAllowedError'?'Microphone permission is required':error.message}}
async function uploadVoice(blob){const status=document.querySelector('#presence');status.textContent='Uploading voice note…';try{const form=new FormData();form.append('file',blob,`voice-note-${Date.now()}.${blob.type.includes('mp4')?'mp4':blob.type.includes('ogg')?'ogg':'webm'}`);const uploaded=await api('/media/upload',{method:'POST',body:form});const payload={text:'Voice message',mediaUrl:uploaded.url,messageType:'audio',mediaSize:blob.size};if(state.socket?.readyState===WebSocket.OPEN)state.socket.send(JSON.stringify({type:'message',...payload}));else{const data=await api(`/chats/${state.active.id}/messages`,{method:'POST',body:JSON.stringify(payload)});state.messages.push(data.message);drawMessages()}status.textContent='Online'}catch(error){status.textContent=error.message}}
async function uploadMedia(file){if(!state.active)return;const status=document.querySelector('#presence');status.textContent='Uploading…';try{const form=new FormData();form.append('file',file);const uploaded=await api('/media/upload',{method:'POST',body:form});const payload={text:file.name,mediaUrl:uploaded.url,messageType:file.type.startsWith('image/')?'image':'file',mediaSize:file.size};if(state.socket?.readyState===WebSocket.OPEN)state.socket.send(JSON.stringify({type:'message',...payload}));else{const data=await api(`/chats/${state.active.id}/messages`,{method:'POST',body:JSON.stringify(payload)});state.messages.push(data.message);drawMessages()}status.textContent='Online';}catch(error){status.textContent=error.message}}
async function loadMedia(url){const response=await fetch(url,{headers:{Authorization:state.token?`Bearer ${state.token}`:''}});if(!response.ok)throw new Error('Unable to load media');return URL.createObjectURL(await response.blob())}
async function markRead(message){if(!message?.id)return;try{await api(`/messages/${message.id}/read`,{method:'POST'});state.socket?.send(JSON.stringify({type:'read',messageId:message.id}))}catch{}}
async function send(e){e.preventDefault();const input=e.target.elements.text;if(!state.active||!input.value.trim())return;const text=input.value.trim();const payload={text,replyToId:state.replyTo?.id||null};try{if(state.socket?.readyState===WebSocket.OPEN)state.socket.send(JSON.stringify({type:'message',...payload}));else{const data=await api(`/chats/${state.active.id}/messages`,{method:'POST',body:JSON.stringify(payload)});state.messages.push(data.message);drawMessages()}input.value='';state.replyTo=null;drawReplyPreview();await refreshChats()}catch(error){document.querySelector('#presence').textContent=error.message}}
applyTheme();
setupPWA();
render();
